<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover"><title><?= htmlspecialchars($store_name ?: 'MartPoint'); ?> — SMS &amp; Email Campaigns</title><link rel="stylesheet" href="<?= $theme_link; ?>css/font-awesome-4.7.0/css/font-awesome.min.css"><style>
:root{--p:#0057ff;--bg:#f1f5f9;--ink:#0f172a;--muted:#64748b;--line:#e2e8f0;--green:#059669}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px system-ui,-apple-system,sans-serif}.screen{max-width:720px;margin:auto;min-height:100vh;padding:14px 14px 125px}.topbar{display:flex;gap:12px;align-items:center;margin:4px 0 16px}.back{font-size:20px;color:var(--p);text-decoration:none}.store{font-size:11px;letter-spacing:.04em;text-transform:uppercase;color:var(--muted);font-weight:700}.topbar h1{font-size:21px;margin:2px 0}.card{background:#fff;border:1px solid var(--line);border-radius:16px;padding:16px;margin-bottom:12px}.card h2{font-size:16px;margin:0 0 12px}.field{margin:12px 0}.field label{display:block;font-size:13px;font-weight:650;margin-bottom:6px}.field input,.field textarea{width:100%;min-height:46px;border:1px solid var(--line);border-radius:11px;padding:11px 12px;font:inherit}.field textarea{min-height:90px;resize:vertical}.mp-select{display:none}.mp-select-wrap{position:relative}.mp-select-trigger{width:100%;display:flex;justify-content:space-between;align-items:center;min-height:46px;border:1px solid var(--line);border-radius:11px;padding:11px 12px;background:#fff;text-align:left;font:inherit;color:var(--ink)}.mp-select-wrap.open .mp-select-trigger{border-radius:11px 11px 0 0}.mp-select-options{display:none;position:relative;border:1px solid var(--line);border-top:0;border-radius:0 0 11px 11px;max-height:220px;overflow-y:auto;background:#fff}.mp-select-wrap.open .mp-select-options{display:block}.mp-select-option{padding:12px;border-bottom:1px solid var(--line)}.mp-select-option.active{background:#eff6ff;color:#1747c9}.submit,.action{min-height:42px;border:0;border-radius:10px;padding:0 14px;background:var(--p);color:white;font-weight:700}.action.secondary{background:#eff6ff;color:#1747c9}.action:disabled{opacity:.55}.hint,.notice{font-size:12px;color:var(--muted);line-height:1.5}.notice{display:none;padding:10px 12px;background:#eff6ff;color:#1747c9;border-radius:10px;margin-bottom:12px}.campaign{border:1px solid var(--line);border-radius:12px;padding:13px;margin-top:10px}.camp-head{display:flex;justify-content:space-between;gap:10px}.camp-name{font-weight:700}.badge{font-size:10px;font-weight:800;border-radius:99px;padding:4px 8px;background:#f1f5f9;color:#475569;text-transform:uppercase}.camp-meta{font-size:12px;color:var(--muted);margin:6px 0 10px}.actions{display:flex;gap:8px;flex-wrap:wrap}.empty{text-align:center;color:var(--muted);padding:20px}
</style></head><body><main class="screen"><header class="topbar"><a class="back" href="<?= base_url('mobile/marketing'); ?>" aria-label="Back"><i class="fa fa-chevron-left"></i></a><div><div class="store"><?= htmlspecialchars($store_name ?: 'MartPoint'); ?></div><h1>SMS &amp; Email Campaigns</h1></div></header>
<div id="notice" class="notice" role="status"></div>
<section class="card"><h2>Create a campaign draft</h2><p class="hint">Provider charges apply to SMS sends and may apply to email. Sends use the provider account configured for this store; this is not currently a MartPoint credit-purchase wallet.</p>
<form id="campaign-form"><input type="hidden" name="<?= $this->security->get_csrf_token_name(); ?>" value="<?= $this->security->get_csrf_hash(); ?>">
<div class="field"><label for="camp-name">Campaign name</label><input id="camp-name" name="name" maxlength="150" required placeholder="e.g. Weekend offer"></div>
<div class="field"><label for="camp-segment">Audience</label><select class="mp-select" id="camp-segment" name="audience" required><option value="">Choose an audience</option><?php foreach($segments as $key=>$seg): ?><option value="key:<?= htmlspecialchars($key); ?>"><?= htmlspecialchars($seg[0]); ?></option><?php endforeach; ?><?php if(!empty($saved)): ?><optgroup label="Saved segments"><?php foreach($saved as $segment): ?><option value="saved:<?= (int)$segment->id; ?>"><?= htmlspecialchars($segment->name); ?></option><?php endforeach; ?></optgroup><?php endif; ?></select><div class="mp-select-wrap" id="segment-wrap"><button type="button" class="mp-select-trigger">Choose an audience <i class="fa fa-chevron-down"></i></button><div class="mp-select-options"></div></div></div>
<div class="field"><label for="camp-channel">Channel</label><select class="mp-select" id="camp-channel" name="channel"><?php if($can_email): ?><option value="email">Email</option><?php endif; ?><?php if($can_sms): ?><option value="sms">SMS</option><?php endif; ?></select><div class="mp-select-wrap" id="channel-wrap"><button type="button" class="mp-select-trigger"></button><div class="mp-select-options"></div></div></div>
<div class="field" id="subject-wrap"><label for="camp-subject">Email subject</label><input id="camp-subject" name="subject" maxlength="255" placeholder="Subject line"></div>
<div class="field"><label for="camp-message">Message</label><textarea id="camp-message" name="message" maxlength="5000" required placeholder="Hi {name}, ..."></textarea><div class="hint">Use {name} to personalize with the customer’s name. SMS length affects provider charges.</div></div>
<button class="submit" id="save-campaign" type="submit"><i class="fa fa-save"></i> Save draft</button></form></section>
<section class="card"><h2>Campaign history</h2><?php foreach($campaigns as $campaign): $audienceLabel=$campaign->segment_id?'Saved audience #'.(int)$campaign->segment_id:($segments[$campaign->segment_key][0]??'Audience'); ?><article class="campaign"><div class="camp-head"><div class="camp-name"><?= htmlspecialchars($campaign->name); ?></div><span class="badge"><?= htmlspecialchars($campaign->status); ?></span></div><div class="camp-meta"><?= htmlspecialchars(strtoupper($campaign->channel)); ?> · <?= htmlspecialchars($audienceLabel); ?> · <?= (int)$campaign->sent_count; ?> sent / <?= (int)$campaign->failed_count; ?> failed</div><div class="actions"><?php if($campaign->status==='draft'): ?><button class="action secondary" type="button" data-campaign="<?= (int)$campaign->id; ?>" data-mode="test">Test send</button><button class="action" type="button" data-campaign="<?= (int)$campaign->id; ?>" data-mode="send">Send</button><?php elseif(in_array($campaign->status,['partial','sending'],true)): ?><button class="action" type="button" data-campaign="<?= (int)$campaign->id; ?>" data-mode="send">Resume</button><?php endif; ?></div></article><?php endforeach; ?><?php if(empty($campaigns)): ?><div class="empty">No campaigns yet. Save a draft above to get started.</div><?php endif; ?></section></main>
<?php $this->load->view('mobile/bottom_nav',['active'=>'more']); ?><?php $this->load->view('mobile/chat'); ?>
<script>(function(){
var form=document.getElementById('campaign-form'),notice=document.getElementById('notice'),channel=document.getElementById('camp-channel'),subjectWrap=document.getElementById('subject-wrap');
function msg(t){notice.textContent=t;notice.style.display='block';window.scrollTo({top:0,behavior:'smooth'})}
function initSelect(id,required){var s=document.getElementById(id),w=document.getElementById(id==='camp-segment'?'segment-wrap':'channel-wrap'),t=w.querySelector('.mp-select-trigger'),list=w.querySelector('.mp-select-options');function draw(){list.innerHTML='';Array.prototype.forEach.call(s.options,function(o){var x=document.createElement('div');x.className='mp-select-option'+(o.selected?' active':'');x.textContent=o.textContent;x.addEventListener('click',function(){s.value=o.value;s.dispatchEvent(new Event('change',{bubbles:true}));t.innerHTML=(o.textContent||'Choose')+' <i class="fa fa-chevron-down"></i>';w.classList.remove('open');list.querySelectorAll('.mp-select-option').forEach(function(y){y.classList.toggle('active',y===x)})});list.appendChild(x)});if(s.options.length){var o=s.options[s.selectedIndex];t.innerHTML=(o.textContent||'Choose')+' <i class="fa fa-chevron-down"></i>'}}draw();t.addEventListener('click',function(){document.querySelectorAll('.mp-select-wrap.open').forEach(function(x){if(x!==w)x.classList.remove('open')});w.classList.toggle('open')});s.addEventListener('change',function(){if(id==='camp-channel'){subjectWrap.style.display=channel.value==='email'?'block':'none'}});}
initSelect('camp-segment',true);initSelect('camp-channel',false);subjectWrap.style.display=channel.value==='email'?'block':'none';document.addEventListener('click',function(e){if(!e.target.closest('.mp-select-wrap'))document.querySelectorAll('.mp-select-wrap.open').forEach(function(w){w.classList.remove('open')})});
function post(url,data){var fd=new FormData();Object.keys(data).forEach(function(k){fd.append(k,data[k])});fd.append('<?= $this->security->get_csrf_token_name(); ?>','<?= $this->security->get_csrf_hash(); ?>');return fetch(url,{method:'POST',body:fd,credentials:'same-origin'}).then(function(r){return r.json()})}
form.addEventListener('submit',function(e){e.preventDefault();var audience=document.getElementById('camp-segment').value.split(':'),btn=document.getElementById('save-campaign');if(!audience[1]){msg('Choose an audience first.');return}btn.disabled=true;post('<?= base_url('marketing/save_campaign'); ?>',{name:document.getElementById('camp-name').value,segment_key:audience[0]==='key'?audience[1]:'',segment_id:audience[0]==='saved'?audience[1]:'',channel:channel.value,subject:document.getElementById('camp-subject').value,message:document.getElementById('camp-message').value}).then(function(r){if(r.status==='success'){msg('Draft saved.');location.reload()}else msg(r.message||'Could not save campaign.')}).catch(function(){msg('Could not save campaign. Check your connection and try again.')}).finally(function(){btn.disabled=false})});
document.querySelectorAll('[data-campaign]').forEach(function(btn){btn.addEventListener('click',function(){var mode=btn.dataset.mode;if(mode==='send'&&!confirm('Send this campaign to its selected audience? Provider charges may apply.'))return;btn.disabled=true;post('<?= base_url('marketing/send_campaign'); ?>',{id:btn.dataset.campaign,test:mode==='test'?'1':''}).then(function(r){msg(r.message||'Campaign action completed.');if(r.status==='success'&&mode==='send')setTimeout(function(){location.reload()},900)}).catch(function(){msg('Campaign action failed. Please try again.')}).finally(function(){btn.disabled=false})})});
})();</script></body></html>
